class Solution {
  public int waysToReachStair(int k) {
    long answer = 0;
    for (int jumps = 0; jumps <= 31; jumps++) {
      long down = (1L << jumps) - k;
      if (down < 0 || down > jumps + 1) continue;
      answer += combination(jumps + 1, (int) down);
    }
    return (int) answer;
  }

  private long combination(int n, int r) {
    r = Math.min(r, n - r);
    long result = 1;
    for (int i = 1; i <= r; i++) result = result * (n - r + i) / i;
    return result;
  }
}
